def point_type(name, fields, srid_map):
    """ Dynamically create a Point subclass.
    """
    class DynamicPoint(Point):
        __slots__ = ['__dict__'] + fields

        def __init__(self, *args, **kwargs):
            super().__init__(*args)
            for field in fields:
                setattr(self, field, kwargs.get(field))

        def __repr__(self):
            fields_str = ', '.join(f'{field}={getattr(self, field)!r}' for field in fields)
            return f"{self.__class__.__name__}({self.x}, {self.y}, {fields_str})"

        @property
        def srid(self):
            return srid_map.get(self.__class__.__name__, None)

    DynamicPoint.__name__ = name
    return DynamicPoint

