            config_dict[filename] = config
        except Exception as e:
            log_record = logging.LogRecord(
                name="config_loader",
                level=logging.ERROR,
                pathname=filename,
                lineno=0,
                msg=str(e),
                args=(),
                exc_info=True
            )
            log_records.append(log_record)

    if overrides:
        for filename in config_dict:
            for section, settings in overrides.items():
                if not config_dict[filename].has_section(section):
                    config_dict[filename].add_section(section)
                for key, value in settings.items():
                    config_dict[filename].set(section, key, value)

